mapper.select:
/* MenuMapper.existsMenu 메뉴ID가 등록되어 있는지 판별 */
SELECT EXISTS (
    SELECT 1
      FROM TB_MENU_M
     WHERE MENU_ID = #{menuId}
)

mapper.insert:
/* MenuMapper.insertMenu 메뉴를 등록 */
INSERT INTO TB_MENU_M (
    MENU_ID, MENU_NM, UPPR_MENU_ID, ALIN_SEQ, MENU_TYPE_CD, USE_YN, PRGM_ID, RMK,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{item.menuId}, #{item.menuNm}, NULLIF(#{item.upprMenuId}, ''), #{item.alinSeq},
    NULLIF(#{item.menuTypeCd}, ''), #{item.useYn}, NULLIF(#{item.prgmId}, ''), NULLIF(#{item.rmk}, ''),
    #{usrId}, CURRENT_TIMESTAMP, #{usrId}, CURRENT_TIMESTAMP
)

mapper.delete:
/* MenuMapper.deleteMenu 메뉴를 삭제 */
DELETE FROM TB_MENU_M
 WHERE MENU_ID = #{menuId}

/* MenuMapper.deleteMenuFavoriteList 메뉴의 즐겨찾기를 모두 삭제 (메뉴 삭제 시) */
DELETE FROM TB_PRGM_FAV_L
 WHERE MENU_ID = #{menuId}

/* MenuMapper.deleteMenuAuthGroupList 메뉴의 권한그룹 메뉴 권한을 모두 삭제 (메뉴 삭제 시) */
DELETE FROM TB_AUTH_GRP_MENU_R
 WHERE MENU_ID = #{menuId}

/* MenuMapper.deleteMenuUserAuthList 메뉴의 사용자 메뉴 권한을 모두 삭제 (메뉴 삭제 시) */
DELETE FROM TB_USR_MENU_R
 WHERE MENU_ID = #{menuId}
